class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def kth_smallest(root_arr, k):
    root = build_tree(root_arr)
    count = [0]
    answer = [None]

    def inorder(node):
        if node is None or answer[0] is not None:
            return
        inorder(node.left)
        if answer[0] is not None:
            return
        count[0] += 1
        if count[0] == k:
            answer[0] = node.val
            return
        inorder(node.right)

    inorder(root)
    return answer[0]

